+export interface Mailer {
+  send(to: string, subject: string, body: string): Promise<void>;
+}
+
+export async function sendOverdueReminder(
+  mailer: Mailer,
+  email: string,
+  daysOverdue: number,
+): Promise<void> {
+  const subject =
+    daysOverdue >= 30
+      ? "Final notice: invoice overdue"
+      : `Reminder: invoice ${daysOverdue} days overdue`;
+  await mailer.send(email, subject, "Please settle the outstanding balance.");
+}

