+import { sendOverdueReminder, Mailer } from "../src/reminder";
+
+describe("sendOverdueReminder", () => {
+  const mailer: Mailer = { send: jest.fn().mockResolvedValue(undefined) };
+
+  it("escalates to a final notice at 30 days", async () => {
+    await sendOverdueReminder(mailer, "a@example.com", 30);
+    expect(mailer.send).toHaveBeenCalledWith(
+      "a@example.com",
+      "Final notice: invoice overdue",
+      expect.any(String),
+    );
+  });
+
+  it("states the days overdue before 30 days", async () => {
+    await sendOverdueReminder(mailer, "b@example.com", 12);
+    expect(mailer.send).toHaveBeenCalledWith(
+      "b@example.com",
+      "Reminder: invoice 12 days overdue",
+      expect.any(String),
+    );
+  });
+});
